#!/usr/bin/env node
'use strict';
//
// Container entrypoint / process supervisor.
//
// Runs TWO processes inside the single container:
//   1. the PRIVATE Express backend  on 127.0.0.1:$BACKEND_PORT (5000)
//   2. the PUBLIC  Next.js frontend on 0.0.0.0:$PORT           (8080, from Cloud Run)
//
// The frontend proxies /api/* to the backend, so only $PORT is ever public.
// If either child exits, we tear the other down so Cloud Run restarts the whole
// container. SIGTERM/SIGINT are forwarded for a graceful shutdown.
//
// ⚠️  Do not edit this file in a vibecoded app — it's platform-owned (see .ai/deploy.md).

const { spawn } = require('node:child_process');
const path = require('node:path');

const ROOT = __dirname;
const PUBLIC_PORT = process.env.PORT || '8080'; // Cloud Run injects PORT
const BACKEND_PORT = process.env.BACKEND_PORT || '5000'; // internal only

/** @type {import('node:child_process').ChildProcess[]} */
const children = [];
let shuttingDown = false;

function start(name, args, cwd, extraEnv) {
  const child = spawn(process.execPath, args, {
    cwd,
    stdio: 'inherit',
    env: { ...process.env, ...extraEnv },
  });
  child.on('exit', (code, signal) => {
    if (shuttingDown) return;
    console.error(`[server] ${name} exited (code=${code} signal=${signal}); shutting down.`);
    shutdown(signal || 'SIGTERM', typeof code === 'number' ? code : 1);
  });
  child.on('error', (err) => {
    console.error(`[server] failed to start ${name}:`, err);
    shutdown('SIGTERM', 1);
  });
  children.push(child);
}

function shutdown(signal, exitCode) {
  if (shuttingDown) return;
  shuttingDown = true;
  let remaining = children.length;
  const done = () => {
    remaining -= 1;
    if (remaining <= 0) process.exit(exitCode);
  };
  for (const child of children) {
    if (child.exitCode === null && child.signalCode === null) {
      child.on('exit', done);
      child.kill(signal);
    } else {
      done();
    }
  }
  // Hard cap so a stuck child can't hang the container.
  setTimeout(() => process.exit(exitCode), 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM', 0));
process.on('SIGINT', () => shutdown('SIGINT', 0));

// 1) Private backend on 127.0.0.1:BACKEND_PORT. The backend reads PORT + HOST.
start('backend', ['dist/index.js'], path.join(ROOT, 'backend'), {
  PORT: BACKEND_PORT,
  HOST: '127.0.0.1',
  NODE_ENV: process.env.NODE_ENV || 'production',
});

// 2) Public Next.js on 0.0.0.0:PORT. The standalone server reads PORT + HOSTNAME.
//    HOSTNAME MUST be 0.0.0.0 or Cloud Run's health check can't reach it.
start('frontend', ['server.js'], path.join(ROOT, 'frontend'), {
  PORT: PUBLIC_PORT,
  HOSTNAME: '0.0.0.0',
});

console.log(
  `[server] started — frontend :${PUBLIC_PORT} (public), backend 127.0.0.1:${BACKEND_PORT} (private)`
);
